using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;
namespace Musikbox {
 public sealed class TagChange {public Song Song;public string Source,Target;public Dictionary<string,string> Fields=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);public string Description;public string ArtworkPath;public bool AppendArtwork;}
 public static class TagFields {
  public static Dictionary<string,string> Read(string path){using(var f=TagLib.File.Create(path)){var t=f.Tag;var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"artist",String.Join("; ",t.Performers)},{"title",t.Title??""},{"album",t.Album??""},{"year",t.Year==0?"":t.Year.ToString()},{"genre",String.Join("; ",t.Genres)},{"comment",t.Comment??""},{"track",t.Track==0?"":t.Track.ToString()+(t.TrackCount>0?"/"+t.TrackCount:"")},{"discnumber",t.Disc.ToString()},{"composer",String.Join("; ",t.Composers)},{"albumartist",String.Join("; ",t.AlbumArtists)},{"_filename",Path.GetFileNameWithoutExtension(path)},{"_extension",Path.GetExtension(path).TrimStart('.')},{"_path",path},{"_directory",Path.GetFileName(Path.GetDirectoryName(path))}};var id=f.GetTag(TagLib.TagTypes.Id3v2,false) as TagLib.Id3v2.Tag;if(id!=null){var frame=TagLib.Id3v2.TextInformationFrame.Get(id,"TRCK",false);if(frame!=null&&frame.Text.Length>0)d["track"]=frame.Text[0];foreach(var extra in id.GetFrames<TagLib.Id3v2.UserTextInformationFrame>())if(!String.IsNullOrEmpty(extra.Description))d[extra.Description]=String.Join("; ",extra.Text);}foreach(string key in d.Keys.ToArray())if(!key.StartsWith("_"))d[key]=MediaMetadata.Decode(d[key]);var info=MediaMetadata.Read(path);foreach(var definition in TagSchema.Fields)d[definition.Key]=TagSchema.Value(info,definition.Key);return d;}}
  public static void Verify(string path,IDictionary<string,string> fields){
   using(var f=TagLib.File.Create(path))foreach(var kv in fields){string actual=null,expected=kv.Value??"";var t=f.Tag;switch(kv.Key.ToLowerInvariant()){
    case "artist":actual=String.Join("; ",t.Performers);expected=String.Join("; ",expected.Split(';').Select(x=>x.Trim()));break;
    case "title":actual=t.Title??"";break;case "album":actual=t.Album??"";break;case "comment":actual=t.Comment??"";break;
    case "genre":actual=String.Join("; ",t.Genres);expected=String.Join("; ",GenreTags.Normalize(expected.Split(';')));break;
    case "year":actual=t.Year==0?"":t.Year.ToString();if(expected=="0")expected="";break;
    case "track":var id=f.GetTag(TagLib.TagTypes.Id3v2,false) as TagLib.Id3v2.Tag;var frame=id==null?null:TagLib.Id3v2.TextInformationFrame.Get(id,"TRCK",false);actual=frame!=null&&frame.Text.Length>0?frame.Text[0]:t.Track==0?"":t.Track.ToString()+(t.TrackCount>0?"/"+t.TrackCount:"");break;
    case "acoustid_id":var aid=f.GetTag(TagLib.TagTypes.Id3v2,false) as TagLib.Id3v2.Tag;var user=aid==null?null:TagLib.Id3v2.UserTextInformationFrame.Get(aid,"Acoustid Id",false);actual=user==null?"":String.Join("; ",user.Text);break;
   }if(actual!=null&&actual!=expected)throw new IOException("Gespeichertes Tagfeld konnte nicht bestätigt werden: "+kv.Key+" ("+path+")");
   }
  }
  public static void Write(string path,IDictionary<string,string> fields){using(var f=TagLib.File.Create(path)){foreach(var kv in fields){string value=kv.Value??"";uint n;switch(kv.Key.ToLowerInvariant()){
   case "artist":f.Tag.Performers=value.Split(';').Select(s=>s.Trim()).ToArray();break;case "title":f.Tag.Title=value;break;case "album":f.Tag.Album=value;break;case "year":if(!UInt32.TryParse(value,out n)&&value!="")throw new ArgumentException("Ungültiges Jahr");f.Tag.Year=n;break;case "genre":GenreTags.Write(f,value.Split(';'));break;case "comment":f.Tag.Comment=value;break;case "acoustid_id":var aid=f.GetTag(TagLib.TagTypes.Id3v2,true) as TagLib.Id3v2.Tag;if(aid==null)throw new ArgumentException("AcoustID für dieses Format nicht unterstützt.");TagLib.Id3v2.UserTextInformationFrame.Get(aid,"Acoustid Id",true).Text=new[]{value};break;case "composer":f.Tag.Composers=value.Split(';');break;case "albumartist":f.Tag.AlbumArtists=value.Split(';');break;case "discnumber":if(!UInt32.TryParse(value,out n))throw new ArgumentException("Ungültige Discnummer");f.Tag.Disc=n;break;
   case "track":if(value.Length==0){f.Tag.Track=f.Tag.TrackCount=0;var empty=f.GetTag(TagLib.TagTypes.Id3v2,false) as TagLib.Id3v2.Tag;if(empty!=null)empty.RemoveFrames("TRCK");break;}var parts=value.Split('/');uint total=0;if(!UInt32.TryParse(parts[0],out n)||(parts.Length>1&&!UInt32.TryParse(parts[1],out total))||parts.Length>2)throw new ArgumentException("Ungültige Tracknummer: "+value);f.Tag.Track=n;f.Tag.TrackCount=total;var id=f.GetTag(TagLib.TagTypes.Id3v2,true) as TagLib.Id3v2.Tag;if(id!=null)TagLib.Id3v2.TextInformationFrame.Get(id,"TRCK",true).Text=new[]{value};break;
   default:if(kv.Key.StartsWith("_"))throw new ArgumentException("Datei-Eigenschaften sind keine Tagfelder");var tag=f.GetTag(TagLib.TagTypes.Id3v2,true) as TagLib.Id3v2.Tag;if(tag==null)throw new ArgumentException("Freies Tagfeld für dieses Format nicht unterstützt: "+kv.Key);TagLib.Id3v2.UserTextInformationFrame.Get(tag,kv.Key,true).Text=new[]{value};break;
  }}f.Save();}}
 }
 public static class TagFormat {
  public static string Expand(string pattern,IDictionary<string,string> values){string s=pattern??""; // Evaluate innermost function first; quotes protect commas.
   for(int pass=0;pass<32;pass++){var m=Regex.Match(s,@"\$(upper|lower|trim|num|replace)\(([^()]*)\)",RegexOptions.IgnoreCase);if(!m.Success)break;var args=Split(m.Groups[2].Value).Select(x=>Expand(x,values)).ToArray();string v=args.Length>0?args[0]:"",r;switch(m.Groups[1].Value.ToLowerInvariant()){case "upper":r=v.ToUpperInvariant();break;case "lower":r=v.ToLowerInvariant();break;case "trim":r=v.Trim();break;case "num":int number,width;if(args.Length!=2||!Int32.TryParse(v.Split('/')[0],out number)||!Int32.TryParse(args[1],out width)||width<1||width>12)throw new ArgumentException("$num benötigt Zahl und Stellenzahl");r=number.ToString(new string('0',width));break;default:if(args.Length!=3)throw new ArgumentException("$replace benötigt drei Argumente");r=v.Replace(args[1],args[2]);break;}s=s.Substring(0,m.Index)+r+s.Substring(m.Index+m.Length);}
   s=Regex.Replace(s,@"%([^%]+)%",m=>{string value;if(!values.TryGetValue(m.Groups[1].Value,out value)||String.IsNullOrWhiteSpace(value))throw new ArgumentException("Fehlende Metadaten: "+m.Value);return value;});if(Regex.IsMatch(s,@"\$\w+\("))throw new ArgumentException("Nicht unterstützte Formatfunktion");return s;
  }
  static string[] Split(string s){var result=new List<string>();var b=new StringBuilder();bool quote=false;foreach(char c in s){if(c=='\''){quote=!quote;continue;}if(c==','&&!quote){result.Add(b.ToString());b.Clear();}else b.Append(c);}if(quote)throw new ArgumentException("Nicht geschlossenes Anführungszeichen");result.Add(b.ToString());return result.ToArray();}
  public static Dictionary<string,string> Parse(string input,string pattern){var keys=new List<string>();var b=new StringBuilder("^");int pos=0;foreach(Match m in Regex.Matches(pattern??"",@"%([^%]+)%")){b.Append(Regex.Escape(pattern.Substring(pos,m.Index-pos)));b.Append("(.*?)");keys.Add(m.Groups[1].Value);pos=m.Index+m.Length;}b.Append(Regex.Escape((pattern??"").Substring(pos)));b.Append("$");if(keys.Count==0)throw new ArgumentException("Das Muster benötigt mindestens ein %Tagfeld%.");var match=Regex.Match(input,b.ToString(),RegexOptions.IgnoreCase);if(!match.Success)throw new ArgumentException("Dateiname/Text passt nicht zum Muster: "+input);var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<keys.Count;i++)if(keys[i]!="dummy")result[keys[i]]=match.Groups[i+1].Value;return result;}
  public static void FileName(string name){if(String.IsNullOrWhiteSpace(name)||name.Length>220||name.IndexOfAny("<>:\"/\\|?*".ToCharArray())>=0||name.Any(c=>c<32)||name.TrimEnd(' ','.')!=name||Regex.IsMatch(name,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\.|$)",RegexOptions.IgnoreCase))throw new ArgumentException("Ungültiger Windows-Dateiname: "+name);}
 }
 public static class TagConversion {
  public static List<TagChange> Plan(IList<Song> songs,int mode,string input,string output,string field){if(songs.Count==0)throw new ArgumentException("Bitte Titel markieren.");if(mode!=0&&mode!=1&&mode!=2)throw new ArgumentException("Unbekannte Tag-Konvertierung.");var result=new List<TagChange>();for(int i=0;i<songs.Count;i++){var song=songs[i];var values=TagFields.Read(song.Source);values["ordner"]=song.FolderName??Path.GetFileName(Path.GetDirectoryName(song.Source));values["acoustid_id"]=song.AcoustidId??"";values["artist"]=song.Artist??"";values["title"]=song.Title??"";values["album"]=song.Album??"";values["year"]=song.Year??"";values["genre"]=song.Genre??"";values["comment"]=song.Comment??"";if(song.Track!=null)values["track"]=song.Track;var change=new TagChange{Song=song,Source=Path.GetFullPath(song.Source),Target=Path.GetFullPath(song.Source)};
    if(mode==0||mode==2){if(mode==2){foreach(var kv in TagFormat.Parse(Path.GetFileNameWithoutExtension(song.Source),input))values[kv.Key]=kv.Value;}string name=TagFormat.Expand(output,values)+Path.GetExtension(song.Source);TagFormat.FileName(name);change.Target=Path.Combine(Path.GetDirectoryName(change.Source),name);change.Description=Path.GetFileName(change.Source)+" → "+name;}
    else if(mode==1){change.Fields=TagFormat.Parse(Path.GetFileNameWithoutExtension(song.Source),input);foreach(string key in change.Fields.Keys.ToArray())if(key.StartsWith("_")||key=="ordner")change.Fields.Remove(key);change.Description=String.Join("; ",change.Fields.Select(kv=>kv.Key+" = "+kv.Value));}
    else {if(String.IsNullOrWhiteSpace(field))throw new ArgumentException("Ziel-Tagfeld fehlt");change.Fields[field.Trim()]=TagFormat.Expand(output,values);change.Description=field+" = "+change.Fields[field.Trim()];}result.Add(change);
   }Validate(result);return result;}
  public static void Validate(IList<TagChange> changes){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var c in changes){if(!File.Exists(c.Source))throw new FileNotFoundException("Quelldatei fehlt",c.Source);if(!seen.Add(c.Target))throw new IOException("Mehrere Dateien erhalten denselben Namen: "+c.Target);if(!String.Equals(c.Target,c.Source,StringComparison.OrdinalIgnoreCase)&&File.Exists(c.Target))throw new IOException("Ziel existiert bereits: "+c.Target);}}
 }
 public static class TrackNumbering {
  public static List<TagChange> Plan(IList<Song> songs,int start,bool total,bool zeros,bool reset){if(start<0||start>999999)throw new ArgumentOutOfRangeException("start");if(songs.Count==0)throw new ArgumentException("Bitte Titel markieren.");var counters=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);var counts=songs.GroupBy(s=>reset?Path.GetDirectoryName(Path.GetFullPath(s.Source)):"",StringComparer.OrdinalIgnoreCase).ToDictionary(g=>g.Key,g=>g.Count(),StringComparer.OrdinalIgnoreCase);var result=new List<TagChange>();foreach(var song in songs){string key=reset?Path.GetDirectoryName(Path.GetFullPath(song.Source)):"";int index;counters.TryGetValue(key,out index);counters[key]=index+1;int width=zeros?Math.Max(2,(start+counts[key]-1).ToString().Length):1;string track=(start+index).ToString(new string('0',width))+(total?"/"+counts[key]:"");result.Add(new TagChange{Song=song,Source=Path.GetFullPath(song.Source),Target=Path.GetFullPath(song.Source),Description=track,Fields=new Dictionary<string,string>{{"track",track}}});}return result;}
 }
}
